extra_head_css:
.dropzone { cursor: pointer; }
    .preview-section { display: flex; gap: 24px; flex-wrap: wrap; }
    .preview-left { flex: 0 0 320px; }
    .preview-right { flex: 1; min-width: 300px; }
    @media (max-width: 768px) { .preview-section { flex-direction: column; } .preview-left { flex: none; width: 100%; } }

    .preview-wrapper {
      background: repeating-conic-gradient(var(--bg-secondary) 0% 25%, var(--bg-primary) 0% 50%) 50% / 20px 20px;
      border:1px solid var(--border-color); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 280px;
    }
    .preview-wrapper img { max-width: 100%; max-height: 50vh; border-radius: 4px; }

    .meta-sections { display: flex; flex-direction: column; gap: 12px; }
    .meta-section {
      background: var(--bg-primary); border:1px solid var(--border-color);
      border-radius: 10px; overflow: hidden;
    }
    .meta-section-header {
      padding: 10px 14px; background: var(--bg-secondary); font-weight: 600;
      font-size: .85rem; cursor: pointer; display: flex; justify-content: space-between;
      align-items: center; user-select: none;
    }
    .meta-section-header:hover { background: rgba(99,102,241,.08); }
    .meta-section-body { padding: 10px 14px; font-size: .78rem; display: none; }
    .meta-section.open .meta-section-body { display: block; }
    .meta-section.open .toggle-icon::after { content: 'â¾'; }
    .toggle-icon::after { content: 'â¸'; }

    .meta-table { width: 100%; border-collapse: collapse; }
    .meta-table tr { border-bottom: 1px solid var(--border-color); }
    .meta-table tr:last-child { border-bottom: none; }
    .meta-table td { padding: 5px 4px; vertical-align: top; }
    .meta-table td:first-child { color: var(--text-secondary); width: 40%; font-weight: 500; }
    .meta-table td:last-child { color: var(--text-primary); word-break: break-all; }

    .gps-link { color: var(--accent); text-decoration: none; }
    .gps-link:hover { text-decoration: underline; }

    .warning-box {
      background: rgba(245,158,11,.1); border:1px solid rgba(245,158,11,.3);
      border-radius: 8px; padding: 10px 14px; font-size: .8rem; color: #f59e0b;
      margin-bottom: 12px;
    }
    .btn-group { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; }
    .no-meta { color: var(--text-secondary); font-style: italic; padding: 20px; text-align: center; }
